package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyProof {
    // A SETTLED or VOID claim takes no more proofs. Stored only if the claim still has its loaded status and count, so
    // a claim settled or voided meanwhile by another user is refused.
    public void apply(@Val Claim claim, Claims claims, Out<ClaimResponse> responseOut) throws ClaimProofRefusedException {
        if (claim.status() == ClaimStatus.SETTLED || claim.status() == ClaimStatus.VOID) {
            throw new ClaimProofRefusedException("A " + claim.status() + " claim takes no more proofs.");
        }
        Claim proved = claims.addProof(claim);
        if (proved == null) {
            throw new ClaimProofRefusedException("The claim changed meanwhile: try again.");
        }
        responseOut.set(ClaimResponse.from(proved));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditClaimProofAdded {
    public void audit(@Val Claim loaded, @Val ClaimResponse proved, People people, ServerHttpConnection connection,
            Audit audit) {
        Person person = people.find(loaded.sheetId(), loaded.personId());
        List<String> fields = new ArrayList<>(List.of("person=" + (person == null ? "" : person.name()),
                "amount=" + proved.amount(), "date=" + proved.date()));
        if (proved.number() != null) {
            fields.add("number=" + proved.number());
        }
        fields.add("proofs=" + proved.proofs());
        audit.record(Audit.line("CLAIM_PROOF_ADDED", loaded.sheetId(), Audit.user(connection),
                fields.toArray(String[]::new)));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestBody;

public class ApplyDefer {
    // Only an OPEN claim is deferred, and only to a date after the sheet's today. Stored only if the claim is still
    // OPEN, so a claim settled or voided meanwhile by another user is refused.
    public void apply(@RequestBody(required = false) DeferRequest body, @Val Claim claim, Claims claims, Sheets sheets,
            Out<ClaimResponse> responseOut) throws ClaimDeferRefusedException {
        if (claim.status() != ClaimStatus.OPEN) {
            throw new ClaimDeferRefusedException("Only an OPEN claim can be deferred.");
        }
        LocalDate until;
        try {
            until = LocalDate.parse(body == null || body.until() == null ? "" : body.until().trim());
        } catch (DateTimeParseException e) {
            throw new ClaimDeferRefusedException("Defer to a date (yyyy-mm-dd).");
        }
        LocalDate today = sheets.today(claim.sheetId());
        if (!until.isAfter(today)) {
            throw new ClaimDeferRefusedException("A claim is deferred only to a date after today (" + today + ").");
        }
        Claim deferred = claims.defer(claim, until);
        if (deferred == null) {
            throw new ClaimDeferRefusedException("Only an OPEN claim can be deferred.");
        }
        responseOut.set(ClaimResponse.from(deferred));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditClaimDeferred {
    public void audit(@Val Claim loaded, @Val ClaimResponse deferred, People people, ServerHttpConnection connection,
            Audit audit) {
        Person person = people.find(loaded.sheetId(), loaded.personId());
        List<String> fields = new ArrayList<>(List.of("person=" + (person == null ? "" : person.name()),
                "amount=" + deferred.amount(), "date=" + deferred.date()));
        if (deferred.number() != null) {
            fields.add("number=" + deferred.number());
        }
        fields.add("until=" + deferred.deferredUntil());
        audit.record(Audit.line("CLAIM_DEFERRED", loaded.sheetId(), Audit.user(connection),
                fields.toArray(String[]::new)));
    }
}
package net.officefloor.hq.app.claim;

/** A proof was added to a SETTLED or VOID claim, or to one changed meanwhile by another user. */
public class ClaimProofRefusedException extends Exception {

    public ClaimProofRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimProofRefused {
    public void handle(@Parameter ClaimProofRefusedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.UNPROCESSABLE_ENTITY));
    }
}
-- How many proofs a claim has been given, raised by one at a time; 0 for a claim given none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- The sheet's void reasons, listed in the order they were added; each reason at most once per sheet, without regard to
-- case. While a sheet has any, a claim is voided only with one of them, kept on the claim (null: voided without one, or
-- not voided). Kept in history too (see V39 and V40); the claim's journal trigger is made again around the change, as
-- in V41.
CREATE TABLE void_reason (
    sheet_id VARCHAR(255) NOT NULL,
    reason VARCHAR(255) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, reason)
);
CREATE TABLE void_reason_history AS SELECT * FROM void_reason;
ALTER TABLE void_reason_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE void_reason_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE void_reason_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
CREATE INDEX void_reason_history_key ON void_reason_history (sheet_id, reason);
CREATE TRIGGER void_reason_journal AFTER INSERT, UPDATE, DELETE ON void_reason FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
DROP TRIGGER claim_journal;
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN void_reason VARCHAR(255);
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';

