package net.officefloor.hq.app.history;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * A screen shown as of a date names it on every request ({@code X-As-Of: yyyy-mm-dd}). A read is answered from the
 * store as it stood at the end of that date (see {@link AsOf}); a change is refused (422) before anything is read,
 * stored or recorded. A request without the header is served as it is now.
 */
@Component
public class AsOfFilter extends OncePerRequestFilter {

    public static final String HEADER = "X-As-Of";

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !request.getRequestURI().startsWith("/api/");
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String raw = request.getHeader(HEADER);
        if (raw == null || raw.isBlank()) {
            chain.doFilter(request, response);
            return;
        }
        LocalDate date;
        try {
            date = LocalDate.parse(raw.trim(), ISO);
        } catch (DateTimeParseException e) {
            refuse(response, HttpStatus.BAD_REQUEST, "The as-of date is not a date (yyyy-mm-dd).");
            return;
        }
        if (!"GET".equals(request.getMethod())) {
            refuse(response, HttpStatus.UNPROCESSABLE_ENTITY,
                    "The sheet is shown as of " + date + ": clear the as-of date to change anything.");
            return;
        }
        LocalDate was = AsOf.set(date);
        try {
            chain.doFilter(request, response);
        } finally {
            AsOf.set(was);
        }
    }

    private static void refuse(HttpServletResponse response, HttpStatus status, String message) throws IOException {
        response.setStatus(status.value());
        response.setContentType("text/plain;charset=UTF-8");
        response.getOutputStream().write(message.getBytes(StandardCharsets.UTF_8));
    }
}
package net.officefloor.hq.app.history;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

/**
 * Reading a sheet as it stood at the end of a date: for a statement taken as of a date, and for a screen shown as of
 * one ({@link AsOfFilter}). While {@link #on} runs its work, the stores read the tables a
 * person's figures come from ({@link #table}) out of their history, each row as the last change made while the sheet's
 * today was on or before the date left it (later changes do not count), and that date stands in for the sheet's today.
 */
public final class AsOf {

    /** The columns that name a row of each table kept in history. */
    private static final Map<String, List<String>> KEYS = Map.ofEntries(
            Map.entry("claim", List.of("id")),
            Map.entry("person", List.of("id")),
            Map.entry("person_grade", List.of("person_id", "from_date")),
            Map.entry("person_hold", List.of("id")),
            Map.entry("rate", List.of("sheet_id", "grade", "from_date")),
            Map.entry("setting", List.of("sheet_id", "setting_key")),
            Map.entry("setting_from", List.of("sheet_id", "setting_key", "from_date")),
            Map.entry("sheet", List.of("id")),
            Map.entry("statement", List.of("id")),
            Map.entry("period", List.of("sheet_id", "name")),
            Map.entry("period_person_total", List.of("sheet_id", "period_name", "person_id")),
            Map.entry("claim_log", List.of("id")),
            Map.entry("person_patron", List.of("person_id", "patron_id")),
            Map.entry("person_watch", List.of("id")),
            Map.entry("delegation", List.of("id")),
            Map.entry("sheet_role", List.of("sheet_id", "user_name")),
            Map.entry("holiday", List.of("sheet_id", "holiday_date")),
            Map.entry("void_reason", List.of("sheet_id", "reason")));

    private static final ThreadLocal<LocalDate> DATE = new ThreadLocal<>();

    private AsOf() {
    }

    /** Runs the work reading the store as it stood at the end of {@code date}. */
    public static <T> T on(LocalDate date, Supplier<T> work) {
        LocalDate was = DATE.get();
        DATE.set(date);
        try {
            return work.get();
        } finally {
            DATE.set(was);
        }
    }

    /** Reads the store as of {@code date} (as it is now when null) until set back; returns the date it was read as of. */
    static LocalDate set(LocalDate date) {
        LocalDate was = DATE.get();
        DATE.set(date);
        return was;
    }

    /** The date the store is read as of; null when it is read as it is now. */
    public static LocalDate date() {
        return DATE.get();
    }

    /** The table to read FROM, named {@code table} in the query: as it is now, or as it stood at the end of the date. */
    public static String table(String table) {
        return table(table, table);
    }

    /** The table to read FROM, named {@code alias} in the query: as it is now, or as it stood at the end of the date. */
    public static String table(String table, String alias) {
        LocalDate date = DATE.get();
        if (date == null) {
            return table + " " + alias;
        }
        String on = "DATE '" + date + "'";
        StringBuilder same = new StringBuilder();
        for (String key : KEYS.get(table)) {
            same.append(" AND x.").append(key).append(" IS NOT DISTINCT FROM h.").append(key);
        }
        return "(SELECT * FROM " + table + "_history h WHERE h.history_on <= " + on + " AND NOT h.history_gone"
                + " AND NOT EXISTS (SELECT 1 FROM " + table + "_history x WHERE x.history_on <= " + on
                + " AND x.history_seq > h.history_seq" + same + ")) " + alias;
    }
}
package net.officefloor.hq.app.history;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.h2.api.Trigger;

/**
 * Copies every row a change writes to its table's history ({@code <table>_history}), with the sheet's today when the
 * change was made; a deleted row is copied as it was, marked gone. See {@link AsOf} for how the history is read back.
 */
public class Journal implements Trigger {

    private List<String> columns;
    private String insert;
    private int sheetColumn;
    private int personColumn;

    @Override
    public void init(Connection conn, String schemaName, String triggerName, String tableName, boolean before, int type)
            throws SQLException {
        columns = new ArrayList<>();
        try (ResultSet rs = conn.getMetaData().getColumns(null, schemaName, tableName, null)) {
            while (rs.next()) {
                columns.add(rs.getString("COLUMN_NAME"));
            }
        }
        // The sheet's own row names its sheet by its id.
        sheetColumn = columns.indexOf("SHEET".equals(tableName) ? "ID" : "SHEET_ID");
        personColumn = columns.indexOf("PERSON_ID");
        insert = "INSERT INTO " + tableName + "_HISTORY (" + String.join(", ", columns)
                + ", HISTORY_ON, HISTORY_GONE) VALUES (" + "?, ".repeat(columns.size()) + "?, ?)";
    }

    @Override
    public void fire(Connection conn, Object[] oldRow, Object[] newRow) throws SQLException {
        Object[] row = newRow != null ? newRow : oldRow;
        try (PreparedStatement ps = conn.prepareStatement(insert)) {
            for (int i = 0; i < columns.size(); i++) {
                ps.setObject(i + 1, row[i]);
            }
            ps.setObject(columns.size() + 1, today(conn, sheetOf(conn, row)));
            ps.setBoolean(columns.size() + 2, newRow == null);
            ps.executeUpdate();
        }
    }

    /** The row's sheet: its own, else its person's. */
    private String sheetOf(Connection conn, Object[] row) throws SQLException {
        if (sheetColumn >= 0) {
            return (String) row[sheetColumn];
        }
        try (PreparedStatement ps = conn.prepareStatement("SELECT sheet_id FROM person WHERE id = ?")) {
            ps.setObject(1, row[personColumn]);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getString(1) : null;
            }
        }
    }

    /** The sheet's today: the real date for a sheet never stored. */
    private static LocalDate today(Connection conn, String sheetId) throws SQLException {
        try (PreparedStatement ps = conn.prepareStatement("SELECT today_date FROM sheet WHERE id = ?")) {
            ps.setString(1, sheetId);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getObject(1, LocalDate.class) : LocalDate.now();
            }
        }
    }
}
